import {tr,local,languages} from './i18n.js';
import {icon as ico} from './icons.js';
import {createAcademy} from './academy-ui.js';
import {courses as seeds,starterCode,courseReferences} from './data.js';
import {actions,spent,simulate,recommendation,parseRoster,csvCell} from './engine.js';

import {studyLabel,readingHTML,workshopHTML,checkpointHTML,caseFileHTML,accessLabHTML,scopeLabHTML,evaluateScope,evaluateAccess,checkAnswer,courseGuideHTML,portfolioText} from './learning-studio.js';

const KEY='forma.workspace.v1';
const fresh=()=>({version:1,lang:'en',role:'learner',profile:{name:'Alex',background:'noCoding',goal:'build',depth:'beginner',learningLanguage:''},courses:[],progress:{},notes:{},code:{},classes:[],people:[],events:[],work:{},checks:{},path:null,game:{selected:[],result:null}});
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'null')};}catch{state=fresh();}
if(!languages[state.lang])state.lang='en';
let academy;
let aiConfigured=false,editorDraft=null,editorLang='en',modalLastFocus=null,toastTimer,gameTimer,worker=null;
let chatContext=null,chatMessages=[],slideIndex=0;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>academy?.label(k)??tr(k,state.lang);
const ll=()=>state.profile.learningLanguage||state.lang;
const text=v=>local(v,state.lang);
const learnText=v=>local(v,ll());
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast(t('localData')+': storage unavailable');}}
function event(type,courseId='',detail={}){state.events.push({type,courseId,time:new Date().toISOString(),...detail});academy?.recordEvent(type,courseId,detail);if(state.events.length>1000)state.events=state.events.slice(-1000);save();}

function allCourses(){const overrides=new Map(state.courses.map(c=>[c.id,c]));return [...seeds.map(c=>({...c,...overrides.get(c.id)})),...state.courses.filter(c=>!seeds.some(s=>s.id===c.id))];}
function getCourse(id){return allCourses().find(c=>c.id===id);}
function learnerCourses(){return allCourses().filter(c=>c.status==='published');}
function learningOrder(){const published=new Set(learnerCourses().map(c=>c.id));return [...new Set([...(state.path||academy?.activePlan()?.steps.map(x=>x.courseId)||recommendation(state.profile)),...recommendation(state.profile),...published])].filter(id=>published.has(id));}
function coursePct(c){return c.lessons.length?Math.round(c.lessons.filter(l=>state.progress[c.id]?.includes(l.id)).length/c.lessons.length*100):0;}
function courseStatus(c){return coursePct(c)===100?'completed':coursePct(c)>0?'inProgress':'notStarted';}
function courseArt(c){const common=`<svg class="art" viewBox="0 0 240 126" fill="none" aria-hidden="true">`;
 if(c.theme==='lavender')return common+`<g transform="rotate(-5 120 65)"><rect x="38" y="13" width="165" height="104" rx="7" fill="#fff" stroke="#d5ceff"/><g fill="#d5ceff"><circle cx="51" cy="25" r="2"/><circle cx="59" cy="25" r="2"/><circle cx="67" cy="25" r="2"/></g><path d="m73 48-13 13 13 13m91-26 13 13-13 13m-39-29-15 34" stroke="#7864be" stroke-width="3" stroke-linecap="round"/><path d="M58 95h86" stroke="#ded9ff" stroke-width="4" stroke-linecap="round"/></g><rect x="161" y="86" width="49" height="25" rx="5" fill="#ffd02f"/><path d="m178 98 5 5 11-12" stroke="#050038" stroke-width="2"/></svg>`;
 if(c.theme==='peach')return common+`<g transform="rotate(-5 86 44)"><path d="M28 20h112a8 8 0 0 1 8 8v39a8 8 0 0 1-8 8H64L47 88V75H28a8 8 0 0 1-8-8V28a8 8 0 0 1 8-8Z" fill="#fff" stroke="#b9afe8"/><path d="M38 39h89M38 52h58" stroke="#d5ceff" stroke-width="4" stroke-linecap="round"/></g><g transform="rotate(5 168 86)"><path d="M121 62h91a7 7 0 0 1 7 7v34a7 7 0 0 1-7 7h-16l-1 10-16-10h-58a7 7 0 0 1-7-7V69a7 7 0 0 1 7-7Z" fill="#e4ddff" stroke="#b9afe8"/><circle cx="145" cy="86" r="3" fill="#605a8a"/><circle cx="165" cy="86" r="3" fill="#605a8a"/><circle cx="185" cy="86" r="3" fill="#605a8a"/></g></svg>`;
 return common+`<g transform="rotate(-7 72 67)"><rect x="22" y="24" width="94" height="85" fill="#ffd02f"/><path d="M38 44h48M38 58h60M38 72h42" stroke="#746019" stroke-width="3" stroke-linecap="round" opacity=".65"/></g><g transform="rotate(4 171 70)"><rect x="126" y="35" width="92" height="73" fill="#fff" stroke="#ded9ff"/><path d="M143 53h53M143 66h41M143 79h47" stroke="#b9afe8" stroke-width="3" stroke-linecap="round"/></g><path d="M101 70h32m-6-5 6 5-6 5" stroke="#605a8a" stroke-width="1.5"/></svg>`;
}
function heroNotes(){return `<div class="sticky-board" aria-hidden="true"><div class="hero-note note-understand"><strong>${t('noteProblem')}</strong></div><div class="hero-note note-build"><strong>${t('noteVersion')}</strong></div><div class="hero-note note-learn"><strong>${t('noteImprove')}</strong></div></div>`;}
const navs={learner:[['learning','home'],['explore','compass'],['path','path'],['practice','code'],['records','chart']],instructor:[['courses','book'],['classrooms','users'],['engagement','chart']],admin:[['overview','home'],['users','users'],['catalog','layers']]};
function route(){return decodeURIComponent(location.hash.slice(1)||'learning').split('/');}
function go(hash){location.hash=hash;}
function render(){
 academy?.beforeRender();
 if(worker){worker.terminate();worker=null;} if('speechSynthesis' in window)speechSynthesis.cancel();
 const [page,id,index]=route();const role=state.role;document.documentElement.lang=state.lang;document.title='Forma — '+t(['learn','course'].includes(page)?'explore':page==='editor'?'editor':page==='game'?'gameLabel':page);
 const navpage=['learn','course','tutorial','reference'].includes(page)?'explore':['lab','challenge','interview','game','playground','next'].includes(page)?'practice':['setup','plan'].includes(page)?'path':page==='editor'?'courses':page;
 const nav=navs[role]||navs.learner;
 $('#app').innerHTML=`<div class="mobile-shade" data-action="mobile"></div><aside class="sidebar"><a href="#${nav[0][0]}" class="brand" aria-label="Forma"><span class="brand-word">forma<span class="brand-period" aria-hidden="true">.</span></span></a><nav aria-label="${esc(t('workspace'))}">${nav.map(([k,i])=>`<a class="nav-link ${navpage===k?'active':''}" href="#${k}">${ico(i,17)}<span>${t(k)}</span>${navpage===k?'<i class="nav-dot"></i>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="account profile-entry" href="#profile" aria-label="${esc(t('profile'))}" ${page==='profile'?'aria-current="page"':''}><span class="avatar">${esc(state.profile.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(state.profile.name)}</strong></div></a></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="mobile" aria-label="${esc(t('workspace'))}">${ico('menu')}</button><span>${t(['learn','course'].includes(page)?'explore':page==='editor'?'editor':page==='game'?'gameLabel':page)}</span></div><div class="top-tools"><label class="language-wrap">${ico('globe',17)}<select id="language" class="language" aria-label="${t('interfaceLanguage')}">${Object.entries(languages).map(([k,v])=>`<option value="${k}" ${state.lang===k?'selected':''}>${v}</option>`).join('')}</select></label><select class="role-select" id="role" aria-label="${t('previewAs')}">${['learner','instructor','admin'].map(k=>`<option value="${k}" ${role===k?'selected':''}>${t(k==='admin'?'adminShort':k)}</option>`).join('')}</select><button class="icon-btn" data-action="about" aria-label="${t('help')}">${ico('help',20)}</button></div></header><div class="content" id="content">${pageContent(page,id,index)}</div></main>`;
 const c=$('#content');c.insertAdjacentHTML('beforeend',`<footer class="footer"><span>© 2026 Forma</span></footer>`);
 bindPage(page,id,index);academy?.afterRender(page,id,index);window.scrollTo({top:0,behavior:'instant'});
}
function heading(title,sub,eyebrow=''){return `<div class="page-heading"><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>`;}
function pageContent(page,id,index){const enhanced=academy?.page(page,id,index);if(enhanced!=null)return enhanced;switch(page){case'learning':return dashboard();case'course':{const c=getCourse(id);return c?courseGuideHTML(c,state,ll(),courseReferences):`<div class="empty">${t('noResults')}</div>`;}case'explore':return explore();case'path':return pathPage();case'profile':return profilePage();case'learn':return lessonPage(id,Number(index)||0);case'game':return gamePage();case'courses':return teacherPage();case'editor':return editorPage(id);case'classrooms':return classroomsPage();case'engagement':return analyticsPage();case'overview':return adminPage();case'users':return usersPage();case'catalog':return catalogPage();default:return dashboard();}}
function card(c){const pct=coursePct(c);return `<article class="course-card"><a href="#course/${c.id}" class="course-art ${c.theme||'mint'}">${courseArt(c)}</a><div class="course-card-body"><h3><a href="#course/${c.id}">${esc(text(c.title))}</a></h3><p>${esc(text(c.description))}</p><div class="course-meta"><span>${ico('clock',11)}${c.duration} ${t('min')}</span><span>${ico('book',11)}${c.lessons.length} ${t('lessons')}</span></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="course-card-bottom"><a href="#learn/${c.id}/${Math.max(0,c.lessons.findIndex(l=>!state.progress[c.id]?.includes(l.id)))}">${t(pct===100?'completed':pct?'continue':'startLearning')}${ico(pct===100?'check':'arrow',12)}</a></div></div></article>`;}
function dashboard(){const cs=learnerCourses().filter(c=>!c.personal);const first=getCourse(learningOrder()[0])||cs[0];const next=Math.max(0,first.lessons.findIndex(l=>!state.progress[first.id]?.includes(l.id)));return `<section class="hero hero-notes"><div class="hero-copy"><h1>${t('dashboardTitle').split(state.lang==='en'?', ' : '，').map((part,i)=>`<span>${esc(part)}${i===0?(state.lang==='en'?',':'，'):''}</span>`).join('')}</h1><p>${t('dashboardSub')}</p><div class="row"><a class="btn" href="#learn/${first.id}/${next}">${t(coursePct(first)>0?'continue':'startLearning')}${ico('arrow',14)}</a><a class="btn ghost" href="#path">${t('viewPath')}${ico('arrow',13)}</a></div></div>${heroNotes()}</section><section class="mt-lg"><div class="section-head"><div><h2>${t('allCourses')}</h2></div><a href="#explore">${t('viewAll')}${ico('arrow',13)}</a></div><div class="course-grid">${cs.map(card).join('')}</div></section><section class="below-grid"><div class="challenge-banner"><div><h2>${t('gameTitle')}</h2><p>${t('gameSub')}</p><a class="btn light small-btn" href="#game">${t('playGame')}${ico('arrow',13)}</a></div></div><div class="profile-card"><span class="round-icon">${ico('path',17)}</span><h3>${t('setProfile')}</h3><p>${t('profileHint')}</p><a class="btn ghost small-btn" href="#profile">${t('setProfile')}${ico('arrow',13)}</a></div></section>`;}
function explore(){return `${heading(t('exploreTitle'),t('exploreSub'),t('explore'))}<div class="toolbar"><label class="search">${ico('search',16)}<input id="course-search" placeholder="${esc(t('search'))}" aria-label="${esc(t('search'))}"></label><select id="topic-filter" class="filter" aria-label="${t('topic')}">${['allTopics','foundations','aiDevelopment','product'].map(k=>`<option value="${k}">${t(k)}</option>`).join('')}</select><button class="btn" data-action="new-personal">${ico('plus',14)}${t('selfStudy')}</button></div><div class="course-grid" id="course-results">${learnerCourses().map(card).join('')}</div><div class="callout mt">${t('selfStudySub')}</div>`;}
function pathPage(){const order=learningOrder();const cs=order.map(getCourse).filter(c=>c?.status==='published');const personal=learnerCourses().filter(c=>c.personal&&!order.includes(c.id));return `${heading(t('pathTitle'),t('pathSub'),t('path'))}<div class="callout row between"><span>${t('background')}: ${t(state.profile.background)} · ${t('goal')}: ${t(state.profile.goal)}</span><a href="#profile" class="btn ghost small-btn">${t('setProfile')}${ico('arrow',12)}</a></div><div class="path-list mt">${[...cs,...personal].map((c,i)=>`<article class="path-item"><div class="path-index">${String(i+1).padStart(2,'0')}</div><div class="grow"><h3>${esc(text(c.title))}</h3><p>${esc(text(c.description))}</p><div class="row mt-sm"><span class="pill green">${t(courseStatus(c))}</span><span class="small muted">${coursePct(c)}%</span></div></div><div class="reorder"><button class="icon-btn" data-action="reorder" data-id="${c.id}" data-dir="-1" aria-label="${t('moveUp')}" ${i===0?'disabled':''}>${ico('up',14)}</button><button class="icon-btn" data-action="reorder" data-id="${c.id}" data-dir="1" aria-label="${t('moveDown')}" ${i===[...cs,...personal].length-1?'disabled':''}>${ico('down',14)}</button></div><a class="btn secondary" href="#learn/${c.id}/0">${t('startLearning')}${ico('arrow',13)}</a></article>`).join('')}</div><button class="btn secondary mt" data-action="new-personal">${ico('plus',14)}${t('selfStudy')}</button>`;}
function selectOptions(keys,value){return keys.map(k=>`<option value="${k}" ${value===k?'selected':''}>${t(k)}</option>`).join('');}
function profilePage(){const p=state.profile;return `${heading(t('profileTitle'),t('profileSub'),t('profile'))}<div class="profile-layout"><form id="profile-form" class="form-card"><div class="form-grid"><div class="field full-field"><label for="profile-name">${t('name')}</label><input id="profile-name" name="name" required maxlength="50" value="${esc(p.name)}"></div><div class="field full-field"><label for="background">${t('background')}</label><select id="background" name="background">${selectOptions(['noCoding','someCoding','experienced'],p.background)}</select></div><div class="field full-field"><label for="goal">${t('goal')}</label><select id="goal" name="goal">${selectOptions(['understand','build','career'],p.goal)}</select></div><div class="field"><label for="depth">${t('depth')}</label><select id="depth" name="depth">${selectOptions(['beginner','advanced'],p.depth)}</select></div><div class="field"><label for="learning-language">${t('learningLanguage')}</label><select id="learning-language" name="learningLanguage"><option value="">${t('interfaceLanguage')}</option>${Object.entries(languages).map(([k,v])=>`<option value="${k}" ${p.learningLanguage===k?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="form-actions"><button class="btn" type="submit">${t('save')}${ico('check',14)}</button></div></form><aside class="stack"><div class="callout">${t('profileHint')}</div><div class="panel"><div class="eyebrow muted">${t('recommended')}</div><h3 class="mt-sm">${t(p.depth)}</h3><p class="small muted mt-sm">${t(p.goal)}</p><a class="btn ghost mt-sm" href="#path">${t('viewPath')}${ico('arrow',13)}</a></div></aside></div>`;}
function lessonPage(id,index){const c=getCourse(id);if(!c||!c.lessons.length)return `<div class="empty">${t('emptyCourse')}<br><a class="btn secondary mt" href="#explore">${t('backCourses')}</a></div>`;const i=Math.max(0,Math.min(index,c.lessons.length-1)),l=c.lessons[i];const body=learnText(l.body)+(state.profile.depth==='advanced'&&c.curriculumVersion&&l.advanced?'\n\n## '+studyLabel('extension',ll())+'\n'+learnText(l.advanced):'');const displayedBody=state.profile.depth==='advanced'&&!c.curriculumVersion?learnText(l.advanced||l.body):body;const fallback=typeof l.body==='object'&&!l.body[ll()]?`<div class="availability">${t('translationFallback')} ${languages[Object.keys(l.body)[0]]||''}</div>`:'';return `<div class="lesson-top"><a href="#course/${c.id}">${ico('back',13)}${studyLabel('courseGuide',ll())}</a><div class="row"><span class="pill">${esc(learnText(c.title))}</span><select id="lesson-depth" class="filter" aria-label="${t('depth')}">${selectOptions(['beginner','advanced'],state.profile.depth)}</select></div></div><div class="lesson-layout"><aside class="outline"><h3>${t('courseOutline')}</h3><div class="outline-items">${c.lessons.map((x,n)=>`<a href="#learn/${c.id}/${n}" class="outline-item ${n===i?'active':''}"><span class="outline-num ${state.progress[id]?.includes(x.id)?'done':''}">${state.progress[id]?.includes(x.id)?ico('check',10):n+1}</span><span>${esc(learnText(x.title))}</span></a>`).join('')}</div><div class="progress-track mt-sm"><div class="progress-fill" style="width:${coursePct(c)}%"></div></div><p class="small muted mt-sm">${coursePct(c)}% ${t('completed')}</p></aside><div><article class="lesson-paper" lang="${esc(ll())}"><span class="eyebrow muted">${String(i+1).padStart(2,'0')} / ${String(c.lessons.length).padStart(2,'0')} · ${t(l.type)}${l.minutes?' · '+l.minutes+' '+t('min'):''}</span><h1>${esc(learnText(l.title))}</h1>${fallback}<div class="lesson-text">${readingHTML(displayedBody)}</div>${i===0&&c.outcomes?`<div class="outcomes"><div class="eyebrow">${t('outcomes')}</div><p>${esc(learnText(c.outcomes))}</p></div>`:''}${activity(c,l,displayedBody)}${workshopHTML(c,l,state,ll())}<div class="mt"><label for="lesson-notes"><strong class="small">${t('notes')}</strong></label><textarea id="lesson-notes" class="notes-area" data-course="${c.id}" data-lesson="${l.id}" placeholder="${esc(t('notesHint'))}">${esc(state.notes[id+':'+l.id]||'')}</textarea></div><div class="lesson-actions"><button class="btn ghost" data-action="download-notes" data-id="${c.id}">${ico('download',13)}${t('download')}</button><button class="btn" data-action="complete" data-id="${c.id}" data-index="${i}">${t(state.progress[id]?.includes(l.id)?'completedLesson':i===c.lessons.length-1?'finishCourse':'markComplete')}${ico('check',14)}</button></div></article><section class="support-panel"><div class="row between"><h3>${t('tutor')}</h3>${aiIndicator()}</div><p>${t('tutorHint')}</p><div class="support-actions"><button class="btn ghost small-btn" data-action="hint">${ico('help',13)}${t('hint')}</button><button class="btn ghost small-btn" data-action="tutor" data-id="${c.id}" data-index="${i}">${ico('spark',13)}${t('askAI')}</button></div><div id="hint-text" class="hint-text hidden">${esc(learnText(l.hint||l.body))}</div></section></div></div>`;}
function aiIndicator(){return `<span class="ai-indicator ${aiConfigured?'on':''}"><i class="status-dot"></i>${t(aiConfigured?'aiReady':'aiSetup')}</span>`;}
function activity(c,l,body){if(l.interview)return caseFileHTML(l,ll())+`<button class="btn secondary mt-sm" data-action="roleplay" data-id="${c.id}" data-index="${c.lessons.indexOf(l)}">${ico('chat',14)}${t(l.mockInterview?'mockInterview':'liveRoleplay')}</button><p class="study-disclosure">${t('liveAiNote')}</p>`;if(l.type==='access')return accessLabHTML(ll());if(l.type==='scope')return scopeLabHTML(ll());if(l.type==='simulation')return `<div class="activity-panel"><h3>${t('gameTitle')}</h3><p>${t('gameSub')}</p><a href="#game" class="btn mt-sm">${t('playGame')}${ico('arrow',14)}</a></div>`;
 if(l.type==='conversation')return `<div class="activity-panel"><h3>${t('scenarioCards')}</h3><p>${t('hiddenBrief')}</p><div class="callout mt-sm">${t('presetInterview')}</div><button class="btn secondary mt-sm" data-action="roleplay" data-id="${c.id}" data-index="${c.lessons.indexOf(l)}">${ico('chat',14)}${t('conversation')}</button></div>`;
 if(l.type==='coding')return `<div class="activity-panel"><h3>${t('coding')}</h3><p>${t('codeHint')}</p><textarea id="code-input" class="code-editor" spellcheck="false" aria-label="JavaScript">${esc(state.code[l.id]??l.starter??starterCode)}</textarea><div class="row between"><button class="btn" data-action="run-code" data-id="${l.id}">${ico('play',13)}${t('runCode')}</button><button class="btn ghost" data-action="reset-code" data-id="${l.id}">${t('resetCode')}</button></div><div id="code-output" role="status"></div>${l.solution?`<details class="study-reference"><summary>${t('referenceCode')}</summary><p class="study-disclosure">${t('referenceCodeNote')}</p><pre class="reference-code"><code>${esc(l.solution)}</code></pre></details>`:''}</div>`;
 if(l.type==='slides'&&l.slides){const frames=l.slides.map(learnText);return `<div class="activity-panel study-storyboard"><div class="study-steps">${frames.map((_,i)=>`<span class="${i===0?'current':''}">${esc(l.stepLabels?.[i]?learnText(l.stepLabels[i]):String(i+1).padStart(2,'0'))}</span>`).join('<i>→</i>')}</div><div class="slide-display"><div class="slide-number">01 / ${frames.length}</div><p id="slide-body">${esc(frames[0])}</p></div><div class="slide-controls"><button class="btn ghost small-btn" data-action="narrate">${ico('play',13)}${t('playNarration')}</button><div class="row"><button class="icon-btn" data-action="slide" data-dir="-1" aria-label="${t('previous')}">${ico('back',14)}</button><button class="icon-btn" data-action="slide" data-dir="1" aria-label="${t('next')}">${ico('arrow',14)}</button></div></div><p class="study-disclosure">${t('narrationHint')}</p></div>`;}if(l.type==='slides')return `<div class="activity-panel"><div class="slide-display"><div class="slide-number">01 / ${body.split(/\n+/).length}</div><p id="slide-body">${esc(body.split(/\n+/)[0])}</p></div><div class="slide-controls"><button class="btn ghost small-btn" data-action="narrate">${ico('play',13)}${t('playNarration')}</button><div class="row"><button class="icon-btn" data-action="slide" data-dir="-1" aria-label="${t('previous')}">${ico('back',14)}</button><button class="icon-btn" data-action="slide" data-dir="1" aria-label="${t('next')}">${ico('arrow',14)}</button></div></div><div class="small muted">${t('narrationHint')}</div></div>`;
 if(l.type==='reflection'&&l.workshop)return '';if(l.type==='reflection')return `<div class="activity-panel"><h3>${t('reflection')}</h3><p>${t('decisionPrompt')}</p></div>`;
 return '';}
function teacherPage(){const cs=allCourses().filter(c=>!c.personal);return `${heading(t('teacherTitle'),t('teacherSub'),t('instructor'))}<div class="row between mt" style="margin-bottom:22px"><span class="muted small">${cs.length} ${t('totalCourses')}</span><button class="btn" data-action="new-course">${ico('plus',14)}${t('newCourse')}</button></div><div class="course-grid">${cs.map(c=>`<article class="course-card"><div class="course-art ${c.theme||'mint'}"><span class="eyebrow">${t('miniCourse')}</span>${courseArt(c)}</div><div class="course-card-body"><h3>${esc(text(c.title))}</h3><p>${esc(text(c.description))}</p><div class="course-meta"><span>${c.lessons.length} ${t('lessons')}</span><span>${c.duration} ${t('min')}</span></div><div class="course-card-bottom"><span class="pill ${c.status==='published'?'green':''}">${t(c.status)}</span><a href="#editor/${c.id}">${t('edit')}${ico('edit',12)}</a></div></div></article>`).join('')}</div><div class="callout mt">${t('draftHidden')}</div>`;}
function editorPage(id){const c=getCourse(id);if(!c)return `<div class="empty">${t('noResults')}</div>`;if(!editorDraft||editorDraft.id!==id){editorDraft=structuredClone(c);editorLang=state.lang;}const d=editorDraft;return `${heading(t('editor'),t('editorHint'))}<form id="editor-form" class="form-card"><div class="row between" style="margin-bottom:22px"><span class="pill ${d.status==='published'?'green':''}">${t(d.status)}</span><div class="row"><select class="filter" id="editor-language" aria-label="${t('courseLanguage')}">${Object.entries(languages).map(([k,v])=>`<option value="${k}" ${editorLang===k?'selected':''}>${v}</option>`).join('')}</select><a class="btn secondary small-btn" href="#learn/${d.id}/0">${t('preview')}${ico('arrow',13)}</a></div></div><div class="form-grid"><div class="field full-field"><label for="edit-title">${t('courseTitle')}</label><input name="title" id="edit-title" required maxlength="180" value="${esc(d.title?.[editorLang]||'')}"></div><div class="field full-field"><label for="edit-description">${t('description')}</label><textarea name="description" id="edit-description" maxlength="1500">${esc(d.description?.[editorLang]||'')}</textarea></div><div class="field"><label for="edit-topic">${t('topic')}</label><select name="topic" id="edit-topic">${selectOptions(['foundations','aiDevelopment','product'],d.topic)}</select></div><div class="field"><label for="edit-duration">${t('duration')}</label><input type="number" min="1" max="600" name="duration" id="edit-duration" value="${d.duration||20}" required></div></div><h3 class="mt">${t('courseOutline')}</h3><div id="edit-lessons">${d.lessons.map((l,i)=>`<section class="editor-lesson" data-lesson="${l.id}"><div class="row between"><h4>${String(i+1).padStart(2,'0')} · ${t('lessons')}</h4><button class="icon-btn" type="button" data-action="remove-lesson" data-id="${l.id}" aria-label="${t('remove')}">${ico('trash',14)}</button></div><div class="form-grid"><div class="field"><label for="title-${l.id}">${t('lessonTitle')}</label><input id="title-${l.id}" data-key="title" required maxlength="180" value="${esc(l.title?.[editorLang]||'')}"></div><div class="field"><label for="type-${l.id}">${t('activityType')}</label><select id="type-${l.id}" data-key="type">${selectOptions(['read','slides','conversation','simulation','coding','reflection','access','scope'],l.type)}</select></div><div class="field full-field"><label for="body-${l.id}">${t('lessonBody')} · ${t('beginner')}</label><textarea id="body-${l.id}" data-key="body" maxlength="12000">${esc(l.body?.[editorLang]||'')}</textarea></div><div class="field full-field"><label for="adv-${l.id}">${t('lessonBody')} · ${t('advanced')}</label><textarea id="adv-${l.id}" data-key="advanced" maxlength="12000">${esc(l.advanced?.[editorLang]||'')}</textarea></div></div></section>`).join('')}</div><button type="button" class="btn secondary mt" data-action="add-lesson">${ico('plus',14)}${t('addLesson')}</button><div class="form-actions"><button type="submit" class="btn secondary">${t('save')}</button><button type="button" class="btn" data-action="publish" data-id="${d.id}">${t('publish')}${ico('check',13)}</button></div></form>`;}
function classroomsPage(){return `${heading(t('classroomTitle'),t('classroomSub'),t('classrooms'))}<div class="row between" style="margin-bottom:24px"><span class="small muted">${state.classes.length} ${t('classrooms')}</span><button class="btn" data-action="new-class">${ico('plus',14)}${t('newClass')}</button></div>${state.classes.length?state.classes.map(c=>`<section class="class-card"><div class="row between"><div><h3>${esc(c.name)}</h3><p class="small muted">${esc(text(getCourse(c.courseId)?.title||''))} · ${c.students.length} ${t('students')}</p></div><button class="btn secondary small-btn" data-action="import" data-id="${c.id}">${ico('plus',12)}${t('importStudents')}</button></div><div class="class-roster">${c.students.length?c.students.map(s=>`<div class="roster-row"><span class="avatar">${esc(s.name.slice(0,1))}</span><div><strong>${esc(s.name)}</strong><br><small>${esc(s.email)}</small></div><span class="small muted" style="margin-left:auto">${t('rosterOnly')}</span><button class="icon-btn" data-action="remove-student" data-id="${c.id}" data-email="${esc(s.email)}" aria-label="${t('remove')}">${ico('close',12)}</button></div>`).join(''):`<p class="small muted">${t('csvHint')}</p>`}</div></section>`).join(''):`<div class="empty">${t('noClasses')}</div>`}`;}
function stats(items){return `<div class="stats-grid">${items.map(([label,num,icon])=>`<div class="stat-card"><div class="row">${ico(icon,15)}${t(label)}</div><strong>${num}</strong></div>`).join('')}</div>`;}
function analyticsPage(){const done=Object.values(state.progress).reduce((s,a)=>s+a.length,0);return `${heading(t('analyticsTitle'),t('analyticsSub'),t('engagement'))}${stats([['minutesDone',done,'book'],['sessions',state.events.length,'activity'],['gameAttempts',state.events.filter(e=>e.type==='game').length,'flag']])}<div class="row between" style="margin-bottom:17px"><h3>${t('localLearner')}</h3><button class="btn secondary small-btn" data-action="export-activity">${ico('download',13)}${t('export')}</button></div><div class="table-wrap"><table><thead><tr><th>${t('course')}</th><th>${t('progress')}</th><th>${t('status')}</th></tr></thead><tbody>${allCourses().map(c=>`<tr><td>${esc(text(c.title))}</td><td><div class="row"><div class="progress-track" style="width:100px"><div class="progress-fill" style="width:${coursePct(c)}%"></div></div>${coursePct(c)}%</div></td><td><span class="pill">${t(courseStatus(c))}</span></td></tr>`).join('')}</tbody></table></div><div class="callout warning mt">${t('localNotice')} ${t('rosterOnly')}</div>`;}
function adminPage(){return `${heading(t('adminTitle'),t('adminSub'),t('admin'))}${stats([['totalCourses',allCourses().filter(c=>!c.personal).length,'book'],['totalClasses',state.classes.length,'users'],['sessions',state.events.length,'activity']])}<div class="below-grid"><div class="panel"><h3>${t('catalog')}</h3><p class="small muted mt-sm">${t('draftHidden')}</p><a href="#catalog" class="btn secondary mt">${t('catalog')}${ico('arrow',14)}</a></div><div class="panel"><h3>${t('users')}</h3><p class="small muted mt-sm">${t('manageRoles')}</p><a href="#users" class="btn secondary mt">${t('users')}${ico('arrow',14)}</a></div></div><div class="callout warning mt">${t('localNotice')}</div>`;}
function usersPage(){return `${heading(t('users'),t('manageRoles'),t('admin'))}<div class="row between" style="margin-bottom:20px"><span class="small muted">${state.people.length} ${t('users')}</span><button class="btn" data-action="new-person">${ico('plus',14)}${t('addPerson')}</button></div>${state.people.length?`<div class="table-wrap"><table><thead><tr><th>${t('name')}</th><th>${t('email')}</th><th>${t('role')}</th><th>${t('status')}</th></tr></thead><tbody>${state.people.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.email)}</td><td><select data-person-role="${p.id}" aria-label="${t('role')}">${selectOptions(['learner','instructor','admin'],p.role)}</select></td><td><select data-person-status="${p.id}" aria-label="${t('status')}">${selectOptions(['active','suspended'],p.status)}</select></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${t('manageRoles')}</div>`}`;}
function catalogPage(){return `${heading(t('catalog'),t('draftHidden'),t('admin'))}<div class="table-wrap"><table><thead><tr><th>${t('course')}</th><th>${t('topic')}</th><th>${t('status')}</th><th></th></tr></thead><tbody>${allCourses().filter(c=>!c.personal).map(c=>`<tr><td>${esc(text(c.title))}</td><td>${t(c.topic)}</td><td><span class="pill ${c.status==='published'?'green':''}">${t(c.status)}</span></td><td><button class="btn secondary small-btn" data-action="toggle-publish" data-id="${c.id}">${t(c.status==='published'?'unpublish':'publish')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function gamePage(){const g=state.game;if(g.result)return resultPage(g.result);return `<section class="game-wrap"><div class="game-top"><div><div class="eyebrow">${t('gameLabel')}</div><h1>${t('gameTitle')}</h1><p class="game-desc">${t('gameIntro')}<br>${t('gameExplain')}</p></div><div class="budget"><strong>${8-spent(g.selected)}</strong><small>${t('budget')}</small></div></div><div class="game-tabs"><span class="current">01 / ${t('plan')}</span><span>02 / ${t('launch')}</span><span>03 / ${t('debrief')}</span></div>${['discovery','features','testing'].map(group=>`<div class="game-section-title">${t(group)}</div><div class="game-actions-grid">${actions.filter(a=>a.group===group).map(a=>`<button class="game-action ${g.selected.includes(a.id)?'selected':''}" data-action="game-toggle" data-id="${a.id}" aria-pressed="${g.selected.includes(a.id)}"><span class="action-icon">${ico(a.icon,19)}</span><div><h4>${t(a.id)}</h4><p>${t(a.id==='investigate'?'investigateDesc':a.id+'Desc')}</p></div><span class="action-cost">${g.selected.includes(a.id)?ico('check',14):a.cost+' ◇'}</span></button>`).join('')}</div>`).join('')}${g.selected.includes('investigate')?`<div class="game-message">${t('hiddenBrief')}</div>`:''}${g.selected.includes('loadTest')?`<div class="game-message">${t(g.selected.includes('queue')?'testSafe':'testRisk')}</div>`:''}<div class="game-footer"><small>${t('ruleLabel')}</small><div class="row"><button class="btn ghost" style="color:#605a8a" data-action="game-reset">${t('reset')}</button><button class="btn light" data-action="launch">${t('ship')}${ico('arrow',14)}</button></div></div></section>`;}
function resultPage(r){return `<section class="game-wrap"><div class="eyebrow">03 / ${t('debrief')}</div><h1>${t('resultTitle')}</h1><p class="game-desc">${t('gameIntro')} · ${spent(state.game.selected)} / 8 ${t('credits')}</p><div class="result-grid"><div class="result-stat"><strong>${r.valid}</strong><span>${t('fairTickets')}</span></div><div class="result-stat"><strong>${r.filled}/200</strong><span>${t('seatUse')}</span></div><div class="result-stat"><strong>${r.complaints}</strong><span>${t('complaints')}</span></div></div><div class="result-list">${r.messages.map(k=>`<div class="result-item ${k.startsWith('no')?'bad':''}">${ico(k.startsWith('no')?'info':'check',15)}<span>${t(k)}</span></div>`).join('')}</div><div class="game-footer"><small>${t('ruleLabel')}</small><div class="row"><a href="#learn/testing-release/2" class="btn secondary" style="border-color:#b9afe8;color:#322b6b">${t('backLesson')}</a><button class="btn light" data-action="game-reset">${t('retry')}${ico('refresh',14)}</button></div></div></section>`;}

function toast(message){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function openModal(title,body,sub='',large=false){modalLastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div><button class="icon-btn" data-action="close-modal" aria-label="${t('close')}">${ico('close',18)}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';academy?.afterModal();setTimeout(()=>$('.modal input,.modal textarea,.modal select,.modal button')?.focus(),0);}
function closeModal(){if(chatContext?.controller)chatContext.controller.abort();chatContext=null;$('#modal-root').innerHTML='';document.body.style.overflow='';modalLastFocus?.focus();}
function persistCourse(c){const i=state.courses.findIndex(x=>x.id===c.id);if(i<0)state.courses.push(structuredClone(c));else state.courses[i]=structuredClone(c);save();}
function newCourse(personal=false){openModal(t(personal?'selfStudy':'newCourse'),`<form id="new-course-form" data-personal="${personal}"><div class="stack"><div class="field"><label for="new-topic">${t('topic')}</label><input id="new-topic" name="topic" required maxlength="180" placeholder="${esc(t('topicPlaceholder'))}"></div><div class="field"><label for="new-requirements">${t('requirements')}</label><textarea id="new-requirements" name="requirements" maxlength="5000"></textarea></div><div class="field"><label for="new-language">${t('courseLanguage')}</label><select id="new-language" name="language">${Object.entries(languages).map(([k,v])=>`<option value="${k}" ${k===ll()?'selected':''}>${v}</option>`).join('')}</select></div><div class="callout ${aiConfigured?'':'warning'}">${aiConfigured?t('generateHint'):t('aiOff')}</div></div><div class="form-actions"><button class="btn secondary" type="submit" name="mode" value="manual">${t('manual')}</button><button class="btn" type="submit" name="mode" value="ai" ${aiConfigured?'':'disabled'}>${ico('spark',14)}${t('generate')}</button></div><div id="generation-result" role="status"></div></form>`,t('generateHint'));}
function collectEditor(){if(!editorDraft||!$('#editor-form'))return;const f=$('#editor-form');const title=f.elements.title.value.trim();editorDraft.title={...editorDraft.title,[editorLang]:title};editorDraft.description={...editorDraft.description,[editorLang]:f.elements.description.value.trim()};editorDraft.topic=f.elements.topic.value;editorDraft.duration=Number(f.elements.duration.value)||20;f.querySelectorAll('.editor-lesson').forEach(el=>{const l=editorDraft.lessons.find(x=>x.id===el.dataset.lesson);if(!l)return;for(const key of ['title','body','advanced'])l[key]={...l[key],[editorLang]:el.querySelector(`[data-key="${key}"]`).value};l.type=el.querySelector('[data-key="type"]').value;});}
function saveEditor(publish=false){collectEditor();if(!editorDraft.title[editorLang]?.trim())return toast(t('required'));if(publish&&(!editorDraft.lessons.length||editorDraft.lessons.some(l=>!l.title[editorLang]?.trim()||!l.body[editorLang]?.trim())))return toast(t('emptyCourse'));if(publish)editorDraft.status='published';persistCourse(editorDraft);toast(t('saved'));if(publish)go(state.role==='learner'?'path':'courses');}
function bindPage(page,id,index){
 if(page==='explore'&&$('#course-search')){
  const filter=()=>{const query=$('#course-search').value.trim().toLowerCase();const topic=$('#topic-filter').value;const cs=learnerCourses().filter(c=>(text(c.title)+' '+text(c.description)).toLowerCase().includes(query)&&(topic==='allTopics'||c.topic===topic));$('#course-results').innerHTML=cs.length?cs.map(card).join(''):`<div class="empty" style="grid-column:1/-1">${t('noResults')}</div>`;};$('#course-search').addEventListener('input',filter);$('#topic-filter').addEventListener('change',filter);
 }
 if(page==='profile')$('#profile-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.name.trim())return;state.profile={...state.profile,...data,name:data.name.trim()};state.path=null;save();render();toast(t('saved'));});
 if(page==='learn'){
  slideIndex=0;
  $('#lesson-notes')?.addEventListener('input',e=>{state.notes[e.target.dataset.course+':'+e.target.dataset.lesson]=e.target.value;save();});
  $('#code-input')?.addEventListener('input',e=>{const c=getCourse(id);state.code[c.lessons[Number(index)||0].id]=e.target.value;save();});
 }
 if(page==='editor')$('#editor-form')?.addEventListener('submit',e=>{e.preventDefault();saveEditor();});
}
function downloadFile(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function aiRequest(action,payload,signal){const response=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,language:ll(),...payload}),signal});let data;try{data=await response.json();}catch{throw new Error(t('aiError'));}if(!response.ok)throw new Error(response.status===503?t('aiOff'):t('aiError'));return data;}
function openChat(courseId,index,roleplay=false){if(!aiConfigured){openModal(t('aiSetup'),`<div class="callout warning">${t('aiOff')}</div><p class="small muted mt">${t('aiSetupText')}</p>`);return;}const c=getCourse(courseId),l=c.lessons[Number(index)||0];chatContext={courseId,index,roleplay,controller:new AbortController()};chatMessages=[];openModal(t(roleplay?(l.mockInterview?'mockInterview':'conversation'):'tutor'),`<div class="chat-box" id="chat-box"><div class="chat-message">${roleplay?esc(t('roleplayOpening')):t('tutorHint')}</div></div><form id="chat-form" class="chat-input"><input name="message" required maxlength="2000" aria-label="${esc(t('askAI'))}" placeholder="${esc(t('askPlaceholder'))}"><button class="btn" type="submit">${t('send')}${ico('arrow',13)}</button></form><p class="small muted mt-sm">${esc(learnText(l.title))}</p>`);}
function runCode(lessonId){const code=$('#code-input').value;state.code[lessonId]=code;save();if(worker)worker.terminate();const tests=[{name:'Unique students',input:[{studentId:'A',name:'Alex'},{studentId:'B',name:'Sam'}]},{name:'Repeated ID',input:[{studentId:'A',name:'Alex'},{studentId:'A',name:'Other'},{studentId:'B',name:'Sam'}]},{name:'Empty input',input:[]},{name:'Same name, different IDs',input:[{studentId:'A',name:'Alex'},{studentId:'B',name:'Alex'}]}];
 const localized=state.lang==='en'?['Unique students','Repeated ID','Empty input','Same name, different IDs']:state.lang==='zh-CN'?['不同学生','重复 ID','空输入','同名不同 ID']:['不同學生','重複 ID','空輸入','同名不同 ID'];
 // A sandboxed opaque-origin iframe owns the worker. The worker itself gets a
 // restrictive CSP, no network, no DOM, and a two-second execution deadline.
 const frame=document.createElement('iframe');frame.hidden=true;frame.sandbox='allow-scripts';frame.srcdoc=`<!doctype html><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline' 'unsafe-eval' blob:; worker-src blob:; connect-src 'none'"><script>let w;addEventListener('message',e=>{if(e.source!==parent)return;const blob=new Blob([e.data.source],{type:'text/javascript'});const u=URL.createObjectURL(blob);w=new Worker(u);w.onmessage=x=>parent.postMessage({type:'forma-code-result',nonce:e.data.nonce,result:x.data},'*');w.onerror=()=>parent.postMessage({type:'forma-code-result',nonce:e.data.nonce,result:{error:true}},'*');w.postMessage(e.data.tests);URL.revokeObjectURL(u)});</script>`;
 const nonce=crypto.randomUUID();const source=`self.fetch=undefined;self.WebSocket=undefined;self.EventSource=undefined;self.importScripts=undefined;self.XMLHttpRequest=undefined;self.onmessage=e=>{try{${code}\nconst results=e.data.map(test=>{const input=test.input;const before=JSON.stringify(input);const expected=input.filter((x,i)=>input.findIndex(y=>y.studentId===x.studentId)===i);const actual=uniqueBookings(input);return Array.isArray(actual)&&actual!==input&&JSON.stringify(actual)===JSON.stringify(expected)&&actual.every((x,i)=>x===expected[i])&&JSON.stringify(input)===before});self.postMessage({results})}catch(e){self.postMessage({error:true,message:String(e.message||e)})}}`;
 let timeout;const cleanup=()=>{clearTimeout(timeout);window.removeEventListener('message',receive);frame.remove();worker=null;};const receive=e=>{if(e.source!==frame.contentWindow||e.data?.nonce!==nonce||e.data?.type!=='forma-code-result')return;const result=e.data.result;cleanup();const ok=!result.error&&result.results.every(Boolean);const output=$('#code-output');if(!output)return;output.className='code-result'+(ok?'':' fail');output.textContent=(ok?t('codePass'):t('codeFail'))+'\n'+(result.results?result.results.map((pass,i)=>(pass?'✓ ':'✕ ')+localized[i]).join('\n'):'');if(result.error&&result.message)output.textContent+='\n'+result.message;event('code',route()[1],{passed:ok,lessonId});};window.addEventListener('message',receive);frame.addEventListener('load',()=>frame.contentWindow.postMessage({source,tests,nonce},'*'),{once:true});document.body.append(frame);timeout=setTimeout(()=>{cleanup();const output=$('#code-output');if(output){output.className='code-result fail';output.textContent=t('codeTimeout');}},2000);worker={terminate:cleanup};}

document.addEventListener('input',e=>{
 if(e.target.dataset.studyDraft!==undefined){const key=e.target.dataset.workKey;state.work??={};state.work[key]??={answers:[],review:[]};state.work[key].answers[Number(e.target.dataset.studyDraft)]=e.target.value;save();const note=e.target.closest('.study-workshop')?.querySelector('.study-save-note');if(note)note.textContent=studyLabel('draftSaved',ll());}
});
document.addEventListener('change',e=>{
 if(e.target.dataset.studyReview!==undefined){const key=e.target.dataset.workKey;state.work??={};state.work[key]??={answers:[],review:[]};state.work[key].review[Number(e.target.dataset.studyReview)]=e.target.checked;save();}
 if(e.target.dataset.studyChoice!==undefined){const key=e.target.dataset.studyChoice;state.checks??={};state.checks[key]??={};state.checks[key].selected=Number(e.target.value);save();}

 if(e.target.id==='language'){collectEditor();state.lang=e.target.value;clearTimeout(toastTimer);$('#toast').classList.remove('show');save();closeModal();render();}
 if(e.target.id==='role'){collectEditor();state.role=e.target.value;save();go(navs[state.role][0][0]);render();}
 if(e.target.id==='lesson-depth'){state.profile.depth=e.target.value;save();render();}
 if(e.target.id==='editor-language'){collectEditor();editorLang=e.target.value;render();}
 if(e.target.dataset.personRole){const p=state.people.find(x=>x.id===e.target.dataset.personRole);p.role=e.target.value;save();toast(t('saved'));}
 if(e.target.dataset.personStatus){const p=state.people.find(x=>x.id===e.target.dataset.personStatus);p.status=e.target.value;save();toast(t('saved'));}
 if(e.target.id==='csv-file'){const file=e.target.files[0];if(file)file.text().then(s=>{$('#csv-input').value=s;});}
});
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
 if(action==='download-work'){const c=getCourse(id);if(c)downloadFile('forma-'+c.id+'-work.txt',portfolioText(c,state,ll()));}
 if(action==='check-answer'){const c=getCourse(id),l=c?.lessons.find(l=>l.id===el.dataset.lesson);if(!l?.check)return;const key=c.id+':'+l.id,answer=state.checks?.[key]?.selected;if(!Number.isInteger(answer))return toast(studyLabel('selectFirst',ll()));state.checks[key].checked=answer;save();event('checkpoint',c.id,{lessonId:l.id,passed:checkAnswer(l.check,answer).correct});el.closest('.study-check').outerHTML=checkpointHTML(c,l,state,ll());}
 if(action==='scope-check'){const result=evaluateScope([...document.querySelectorAll('[data-scope-option]:checked')].map(x=>x.dataset.scopeOption));const out=$('#scope-result');out.className='study-feedback '+(result.overBudget?'revise':'correct');out.innerHTML='<strong>'+esc(studyLabel('scopeTotal',ll()))+': '+result.cost+' / 6</strong><p>'+esc(studyLabel(result.overBudget?'scopeOver':'scopeWithin',ll()))+'</p>'+(result.unresolvedPolicy?'<p>'+esc(studyLabel('scopePolicy',ll()))+'</p>':'');event('scope-lab',route()[1],{lessonId:'p2',...result});}
 if(action==='access-check'){const result=evaluateAccess({actor:$('#access-actor').value,action:$('#access-action').value,itemState:$('#access-state').value});const out=$('#access-result');out.className='study-feedback '+(result.allowed?'correct':'revise');out.innerHTML='<strong>'+esc(studyLabel(result.allowed?'allow':'deny',ll()))+'</strong><p>'+esc(studyLabel(result.reason,ll()))+'</p>';event('access-lab',route()[1],{lessonId:getCourse(route()[1])?.lessons[Number(route()[2])||0]?.id,allowed:result.allowed});}
 if(action==='mobile'){document.querySelector('.sidebar')?.classList.toggle('open');document.querySelector('.mobile-shade')?.classList.toggle('open');}
 if(action==='about')openModal(t('help'),`<div class="callout">${t('aboutText')}</div><div class="mt small muted">${t('aiSetupText')}</div>`);
 if(action==='close-modal')closeModal();
 if(action==='new-personal')newCourse(true);
 if(action==='new-course')newCourse(false);
 if(action==='hint')$('#hint-text').classList.toggle('hidden');
 if(action==='tutor'||action==='roleplay')openChat(id,Number(el.dataset.index),action==='roleplay');
 if(action==='complete'){const c=getCourse(id),i=Number(el.dataset.index),l=c.lessons[i];state.progress[id]??=[];if(!state.progress[id].includes(l.id)){state.progress[id].push(l.id);event('lesson',id,{lessonId:l.id});}save();toast(t('completedLesson'));go(`next/${id}/${i}`);}
 if(action==='download-notes'){const c=getCourse(id);const content=c.lessons.map(l=>learnText(l.title)+'\n'+(state.notes[id+':'+l.id]||'')).join('\n\n');downloadFile('forma-notes.txt',content);}
 if(action==='game-toggle'){const g=state.game,entry=actions.find(x=>x.id===id);if(g.selected.includes(id))g.selected=g.selected.filter(x=>x!==id);else if(spent(g.selected)+entry.cost<=8)g.selected.push(id);else return toast(t('noBudget'));save();render();}
 if(action==='game-reset'){clearTimeout(gameTimer);state.game={selected:[],result:null};save();render();}
 if(action==='launch'){
  const selected=[...state.game.selected];$('.game-wrap').innerHTML=`<div class="launch-animation"><div class="spinner"></div><div class="eyebrow">02 / ${t('launch')}</div><h2 class="mt-sm">${t('launching')}</h2><div class="launch-dots">${Array.from({length:18},(_,i)=>`<i style="animation-delay:${i*60}ms"></i>`).join('')}</div></div>`;
  clearTimeout(gameTimer);gameTimer=setTimeout(()=>{state.game.result=simulate(selected);event('game','testing-release',{selected,result:state.game.result});save();if(route()[0]==='game')render();},1400);
 }
 if(action==='reorder'){const order=learningOrder();const i=order.indexOf(id),j=i+Number(el.dataset.dir);if(i>=0&&j>=0&&j<order.length){[order[i],order[j]]=[order[j],order[i]];state.path=order;save();render();}}
 if(action==='add-lesson'){collectEditor();editorDraft.lessons.push({id:'l-'+crypto.randomUUID(),title:{[editorLang]:''},body:{[editorLang]:''},advanced:{[editorLang]:''},type:'read'});render();}
 if(action==='remove-lesson'){collectEditor();editorDraft.lessons=editorDraft.lessons.filter(l=>l.id!==id);render();}
 if(action==='publish')saveEditor(true);
 if(action==='toggle-publish'){const c=structuredClone(getCourse(id));if(c.status!=='published'&&!c.lessons.length)return toast(t('emptyCourse'));c.status=c.status==='published'?'draft':'published';persistCourse(c);render();}
 if(action==='new-class'){openModal(t('newClass'),`<form id="new-class-form" class="stack"><div class="field"><label for="class-name">${t('className')}</label><input id="class-name" name="name" required maxlength="100"></div><div class="field"><label for="class-course">${t('course')}</label><select id="class-course" name="courseId">${allCourses().filter(c=>!c.personal&&c.status==='published').map(c=>`<option value="${c.id}">${esc(text(c.title))}</option>`).join('')}</select></div><div class="form-actions"><button class="btn" type="submit">${t('newClass')}</button></div></form>`);}
 if(action==='import')openModal(t('importStudents'),`<form id="import-form" data-id="${id}"><div class="callout">${t('csvHint')}</div><div class="field mt"><label for="csv-file">CSV</label><input type="file" id="csv-file" accept=".csv,text/csv"><textarea id="csv-input" name="csv" required placeholder="name,email&#10;Alex,alex@example.edu&#10;Sam,sam@example.edu" style="min-height:160px"></textarea></div><div class="form-actions"><button class="btn" type="submit">${t('import')}</button></div></form>`);
 if(action==='remove-student'){const c=state.classes.find(c=>c.id===id);c.students=c.students.filter(s=>s.email!==el.dataset.email);save();render();}
 if(action==='new-person')openModal(t('addPerson'),`<form id="person-form" class="stack"><div class="field"><label for="person-name">${t('name')}</label><input id="person-name" name="name" required maxlength="80"></div><div class="field"><label for="person-email">${t('email')}</label><input id="person-email" name="email" required type="email" maxlength="180"></div><div class="field"><label for="person-role">${t('role')}</label><select id="person-role" name="role">${selectOptions(['learner','instructor','admin'],'learner')}</select></div><div class="form-actions"><button class="btn" type="submit">${t('save')}</button></div></form>`);
 if(action==='export-activity'){const rows=[['timestamp','type','course','lesson','result'],...state.events.map(x=>[x.time,x.type,x.courseId,x.lessonId||'',JSON.stringify(x.result??x.passed??'')])];downloadFile('forma-activity.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
 if(action==='run-code')runCode(id);
 if(action==='reset-code'){const [,cid,index]=route();const l=getCourse(cid)?.lessons[Number(index)||0];const code=l?.starter??starterCode;$('#code-input').value=code;state.code[id]=code;save();}
 if(action==='slide'){const [,cid,n]=route();const c=getCourse(cid),l=c.lessons[Number(n)||0];const slides=l.slides?l.slides.map(learnText):learnText(state.profile.depth==='advanced'?(l.advanced||l.body):l.body).split(/\n+/);if('speechSynthesis' in window)speechSynthesis.cancel();slideIndex=(slideIndex+Number(el.dataset.dir)+slides.length)%slides.length;$('.slide-number').textContent=String(slideIndex+1).padStart(2,'0')+' / '+slides.length;$('#slide-body').textContent=slides[slideIndex];document.querySelectorAll('.study-steps span').forEach((node,i)=>node.classList.toggle('current',i===slideIndex));const voice=document.querySelector('[data-action="narrate"]');if(voice)voice.innerHTML=ico('play',13)+t('playNarration');}
 if(action==='narrate'){if(!('speechSynthesis' in window))return toast(t('narrationUnavailable'));if(speechSynthesis.speaking){speechSynthesis.cancel();el.innerHTML=ico('play',13)+t('playNarration');return;}const utterance=new SpeechSynthesisUtterance($('#slide-body').textContent);utterance.lang=ll()==='en'?'en-US':ll();utterance.rate=.93;utterance.onend=()=>{if(el.isConnected)el.innerHTML=ico('play',13)+t('playNarration');};utterance.onerror=()=>toast(t('narrationUnavailable'));speechSynthesis.speak(utterance);el.innerHTML=ico('stop',13)+t('stopNarration');}
});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!['new-course-form','new-class-form','import-form','person-form','chat-form'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));
 if(f.id==='new-course-form'){
  if(!data.topic.trim())return toast(t('required'));const personal=f.dataset.personal==='true',language=data.language;
  const c={id:'course-'+crypto.randomUUID(),title:{[language]:data.topic.trim()},description:{[language]:data.requirements.trim()},topic:'foundations',duration:20,status:'draft',theme:'mint',personal,lessons:[]};
  if(e.submitter?.value==='template'){Object.assign(c,academy.template(data.topic.trim(),c.id),{personal,status:'draft'});}
  else if(e.submitter?.value==='ai'){
   const buttons=f.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);$('#generation-result').textContent=t('thinking');
   try{const response=await aiRequest('generate',{language,topic:data.topic,requirements:data.requirements,profile:state.profile});const draft=response.course;c.title={[language]:draft.title};c.description={[language]:draft.description};c.lessons=draft.lessons.map(l=>({id:'l-'+crypto.randomUUID(),title:{[language]:l.title},body:{[language]:l.body},advanced:{[language]:l.advanced||l.body},type:'read'}));c.duration=c.lessons.length*7;}
   catch(err){Object.assign(c,academy.template(data.topic.trim(),c.id),{personal,status:'draft',generationFallback:true});}
  }else c.lessons=[{id:'l-'+crypto.randomUUID(),title:{[language]:data.topic.trim()},body:{[language]:data.requirements.trim()},advanced:{[language]:''},type:'read'}];
  persistCourse(c);editorDraft=structuredClone(c);editorLang=language;closeModal();go('editor/'+c.id);toast(t('created'));
 }
 if(f.id==='new-class-form'){if(!data.name.trim()||!getCourse(data.courseId))return toast(t('required'));state.classes.push({id:'class-'+crypto.randomUUID(),name:data.name.trim(),courseId:data.courseId,students:[]});save();closeModal();render();toast(t('saved'));}
 if(f.id==='import-form'){const roster=parseRoster(data.csv);if(!roster.length)return toast(t('invalidCsv'));const c=state.classes.find(c=>c.id===f.dataset.id);const emails=new Set(c.students.map(s=>s.email));const added=roster.filter(s=>!emails.has(s.email));c.students.push(...added);save();closeModal();render();toast(t('imported')+' · '+added.length);}
 if(f.id==='person-form'){if(!data.name.trim()||!/^\S+@[^\s@]+\.[^\s@]+$/.test(data.email))return toast(t('invalidName'));if(state.people.some(p=>p.email.toLowerCase()===data.email.toLowerCase()))return toast(t('invalidName'));state.people.push({id:crypto.randomUUID(),...data,name:data.name.trim(),status:'active'});save();closeModal();render();toast(t('saved'));}
 if(f.id==='chat-form'){
  const ctx=chatContext;if(!ctx)return;const message=data.message.trim();if(!message)return;const c=getCourse(ctx.courseId),l=c.lessons[ctx.index];chatMessages.push({role:'user',content:message});$('#chat-box').insertAdjacentHTML('beforeend',`<div class="chat-message user">${esc(message)}</div>`);f.reset();const btn=f.querySelector('button');btn.disabled=true;btn.textContent=t('thinking');
  try{const response=await aiRequest(ctx.roleplay?'roleplay':'tutor',{profile:state.profile,roleplayMode:l.mockInterview?'interviewer':'stakeholder',context:learnText(c.title)+'\n'+learnText(l.title)+'\n'+learnText(l.body)+(l.interview?'\nAuthored practice extracts:\n'+l.interview.map(x=>learnText(x.person)+': '+learnText(x.question)+' '+learnText(x.answer)).join('\n'):''),messages:chatMessages.slice(-12)},ctx.controller.signal);if(chatContext!==ctx)return;chatMessages.push({role:'assistant',content:response.content});$('#chat-box').insertAdjacentHTML('beforeend',`<div class="chat-message">${esc(response.content)}</div>`);$('#chat-box').scrollTop=$('#chat-box').scrollHeight;event('ai',c.id,{lessonId:l.id});}
  catch(err){if(err.name!=='AbortError'&&chatContext===ctx)toast(err.message);}
  finally{if(btn.isConnected){btn.disabled=false;btn.innerHTML=t('send')+ico('arrow',13);f.querySelector('input').focus();}}
 }
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const elements=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.offsetParent!==null);if(!elements.length)return;if(e.shiftKey&&document.activeElement===elements[0]){e.preventDefault();elements.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===elements.at(-1)){e.preventDefault();elements[0].focus();}}});
window.addEventListener('hashchange',()=>{collectEditor();render();});
academy=createAcademy({state:()=>state,save,render,go,route,esc,ico,label:t,courses:allCourses,course:getCourse,card,heroNotes,basePath:pathPage,editor:()=>editorDraft,openModal,closeModal,toast,download:downloadFile,ai:aiRequest,aiReady:()=>aiConfigured});
render();
fetch('/api/ai').then(r=>r.json()).then(data=>{aiConfigured=!!data.configured;document.querySelectorAll('.ai-indicator').forEach(el=>{el.outerHTML=aiIndicator();});}).catch(()=>{});
